import{_ as i,o as a,c as s,ao as t}from"./chunks/framework.DYwHYcTs.js";const g=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md","lastUpdated":null}'),n={name:"installation.md"};function l(h,e,p,o,r,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h1><p>SpeedyWeather.jl is registered in the Julia Registry. In most cases just open the <a href="https://docs.julialang.org/en/v1/stdlib/REPL/" target="_blank" rel="noreferrer">Julia REPL</a> and type</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SpeedyWeather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>or, equivalently, (<code>]</code> opens the package manager)</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] add SpeedyWeather</span></span></code></pre></div><p>which will automatically install the <a href="https://github.com/SpeedyWeather/SpeedyWeather.jl/releases" target="_blank" rel="noreferrer">latest release</a> and all necessary dependencies. If you run into any troubles please raise an <a href="https://github.com/SpeedyWeather/SpeedyWeather.jl/issues/new" target="_blank" rel="noreferrer">issue</a>.</p><h2 id="Installing-main" tabindex="-1">Installing main <a class="header-anchor" href="#Installing-main" aria-label="Permalink to &quot;Installing main {#Installing-main}&quot;">​</a></h2><p>On the branch <code>main</code> we develop SpeedyWeather. This branch contains the latest bug fixes and features that have not been released yet but there might also be issues with <code>main</code> we have not fixed yet. If you need to install that latest version from main do</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/SpeedyWeather/SpeedyWeather.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, subdir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SpeedyWeather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>rev</code> (revision) refers to the <code>main</code> branch, and <code>subdir</code> is needed as we have structured SpeedyWeather as a monorepo with other packages living in the same repository (do <code>subdir=&quot;RingGrids&quot;</code> for example if you want to install the latest unreleased version of the RingGrids package ...). In a similar manner, you can also install other branches than <code>main</code>, e.g. from a specific pull request.</p><p>In brief you can do the same as</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@v1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add SpeedyWeather</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SpeedyWeather</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#main</span></span></code></pre></div><p>following a <code>Repository:Subdirectory#branch</code> logic. Note that installing <code>main</code> gives you the latest unreleased version of SpeedyWeather but the latest released versions of its subpackages. When we move things between these packages then you may run into issues here. In that case you need to <code>develop</code> the package as outlined in the next section.</p><h2 id="Developing-SpeedyWeather" tabindex="-1">Developing SpeedyWeather <a class="header-anchor" href="#Developing-SpeedyWeather" aria-label="Permalink to &quot;Developing SpeedyWeather {#Developing-SpeedyWeather}&quot;">​</a></h2><p>Julia&#39;s package manager Pkg.jl allows another way to develop/use the latest version on main</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">develop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/SpeedyWeather/SpeedyWeather.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, subdir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SpeedyWeather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>in brief you can do this in the pkg shell with</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@v1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dev SpeedyWeather</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SpeedyWeather</span></span></code></pre></div><p>The first &quot;SpeedyWeather&quot; refers to the repository the second to the subdirectory (which could be RingGrids, etc. as well) as also declared above. See the <a href="https://pkgdocs.julialang.org/dev/managing-packages/#Managing-Packages" target="_blank" rel="noreferrer">Managing packages</a> section in the Pkg documentation to learn more about the differences between <code>add</code> and <code>dev</code>.</p><h2 id="Compatibility-with-Julia-versions" tabindex="-1">Compatibility with Julia versions <a class="header-anchor" href="#Compatibility-with-Julia-versions" aria-label="Permalink to &quot;Compatibility with Julia versions {#Compatibility-with-Julia-versions}&quot;">​</a></h2><p>SpeedyWeather.jl requires Julia v1.10 or later. The package is tested on Julia 1.10, 1.11 and 1.12.</p><h2 id="Extensions" tabindex="-1">Extensions <a class="header-anchor" href="#Extensions" aria-label="Permalink to &quot;Extensions {#Extensions}&quot;">​</a></h2><p>SpeedyWeather.jl and its submodules have several weak dependencies for visualisation (Makie, GeoMakie), differentiability (Enzyme, FiniteDifferences) or GPU computing (CUDA, AMDGPU, Metal). These are all <a href="https://pkgdocs.julialang.org/v1.10/creating-packages/#Conditional-loading-of-code-in-packages-(Extensions)" target="_blank" rel="noreferrer">extensions</a>, meaning that this functionality is only loaded from SpeedyWeather (or its submodules) when <code>using Makie</code> etc. Hence, if you want to make use of this extension (some <a href="/./SpeedyWeatherDocumentation/v0.22/examples_2D#Examples">Examples</a> show this) you need to install Makie.jl etc. manually.</p><p>You can see the extensions in the respective <code>ext</code> folders within the submodule folders of the monorepo.</p>`,24)])])}const c=i(n,[["render",l]]);export{g as __pageData,c as default};
